const http = this.helpers.httpRequest;

const SUPABASE_URL = 'https://zavabpchdvssvdnwtuyu.supabase.co';
const SUPABASE_KEY = 'eyJhbG…WDm4';

async function getSubscribers() {
  const url = SUPABASE_URL + '/rest/v1/alert_subscribers?product=eq.trm&active=eq.true&select=phone,plan,config';
  try {
    const data = await http({ method: 'GET', url, headers: { 'apikey': SUPABASE_KEY, 'Authorization': '***' + SUPABASE_KEY } });
    return Array.isArray(data) ? data : [];
  } catch (e) { return []; }
}

// 1. Fetch TRM
const resp = await http({ method: 'GET', url: 'https://open.er-api.com/v6/latest/USD' });
const cop = resp.rates?.COP || resp.rates?.cop;
if (!cop) throw new Error('TRM API failed');

// 2. Fetch subscribers with thresholds configured
const subscribers = await getSubscribers();
const withThreshold = subscribers.filter(s => s.config && (s.config.umbral_alto || s.config.umbral_bajo));

if (withThreshold.length === 0) {
  return { trm: cop, sent: 0, message: 'No subscribers with thresholds configured' };
}

// 3. Check each subscriber's threshold and send alerts
const results = [];
for (const sub of withThreshold) {
  const alto = sub.config.umbral_alto || 999999;
  const bajo = sub.config.umbral_bajo || -1;

  let text = null;
  if (cop >= alto) {
    text = '🚨 *ALERTA TRM ALTA* 🚨\n\n' +
      '🇺🇸 1 USD = 🇨🇴 $' + cop.toLocaleString('es-CO') + ' COP\n\n' +
      '⚠️ El dólar superó los $' + Number(alto).toLocaleString('es-CO') + '\n' +
      '📈 Momento de vender dólares o ajustar precios de importación.\n\n' +
      '⚡ *TRM Alertas*';
  } else if (cop <= bajo) {
    text = '🟢 *ALERTA TRM BAJA* 🟢\n\n' +
      '🇺🇸 1 USD = 🇨🇴 $' + cop.toLocaleString('es-CO') + ' COP\n\n' +
      '✅ El dólar bajó de $' + Number(bajo).toLocaleString('es-CO') + '\n' +
      '💡 Buen momento para comprar dólares o importar.\n\n' +
      '⚡ *TRM Alertas*';
  }

  if (!text) continue;

  try {
    await http({
      method: 'POST',
      url: 'http://148.230.90.171:8096/message/sendText/wasapea-7c7a2c6c',
      headers: { 'apikey': 'wasapea-evo-key-2026', 'Content-Type': 'application/json' },
      body: { number: sub.phone, text: text }
    });
    results.push({ phone: sub.phone, trm: cop, threshold: cop >= alto ? 'ALTO' : 'BAJO', status: 'sent' });
  } catch (e) {
    results.push({ phone: sub.phone, status: 'error', error: e.message });
  }
}

return { trm: cop, triggered: results.length, totalSubs: withThreshold.length, results };
